import re

from robot.api import logger

from ta_egate_cmd_parser.egate_output_parser_base import EgateDispCommandsOutputParser
from ta_egate_cmd_parser.egate_command_base import EgateCommandBase
from ta_egate_cmd_parser.utils.converters import create_dict_with_key


class SimStateDispFailure(Exception):
    """
    Exception class for sim_state_disp
    """
    pass


class SimStateDisp(EgateCommandBase):
    """
    Parser for sim_state_disp command output.
    """
    def __init__(self, **params):
        """

        :param params:
        """
        super(SimStateDisp, self).__init__()
        self.command = 'sim_state_disp'
        self.params = params
        self.state_regexp = 'The state is (.*?)\r?\n'
        self.fail_regexp = 'Error'
        self.executed_phrase = r'The state is.*?EGATE>\s*$'
        self.to_execute = self.command
        logger.debug('{}: {} command to execute:\n{}'.format(self.__class__.__name__, self.command, self.to_execute))

    def execute_and_parse(self, egate_id=0):
        """
        Execute egate cmd and parse its output.
        :return: parsed output
        """
        status, output = super(SimStateDisp, self).execute(egate_id=egate_id, command=self.to_execute)
        if status:
            cmd_parser = EgateDispCommandsOutputParser(output)
            sim_state = re.search(self.state_regexp, output).group(1)
            output = cmd_parser.get_list_of_output_parsed_lines()
            output_dict = create_dict_with_key(key='Device',
                                               list_of_output_parsed_lines=output)
            short_key_output_dict = {key.split()[0]: value for key, value in list(output_dict.items())}
            short_key_output_dict['sim_state'] = sim_state
            return status, short_key_output_dict
        else:
            raise SimStateDispFailure(output)
